132: function sampleTerrain(x, y) {
133:   const roadDistance = getRoadDistance(x, y);
134:   if (roadDistance < 60) return { ...terrainTypes.road, type: 'road', traction: 1.0, drag: 0.99, surface: 0.22 };
135: 
136:   const riverDistance = getRiverDistance(x, y);
137:   if (riverDistance < 50) return { ...terrainTypes.water, type: 'water', traction: 0.36, drag: 0.8, surface: 1.05 };
138: 
139:   if (y > 1170 && x < 740) {
140:     return { ...terrainTypes.peat, type: 'peat', traction: 0.28, drag: 0.6, surface: 1.4 };
141:   }
142: 
143:   if (x > 820 && x < 1200 && y < 1000) {
144:     return { ...terrainTypes.mud, type: 'mud', traction: 0.42, drag: 0.7, surface: 0.9 };
145:   }
146: 
147:   const n = Math.sin(x * 0.014) * Math.cos(y * 0.017 + 1.7) + Math.sin((x + y) * 0.02) * 0.7;
148:   if (n > 0.62) return { ...terrainTypes.snow, type: 'snow', traction: 0.7, drag: 0.97, surface: 0.52 };
149:   if (n < -0.25) return { ...terrainTypes.rock, type: 'rock', traction: 0.58, drag: 0.9, surface: 0.68 };
150:   return { ...terrainTypes.mud, type: 'mud', traction: 0.44, drag: 0.76, surface: 0.82 };
