153: function getRoadDistance(x, y) {
154:   let best = Infinity;
155:   for (let i = 0; i < world.route.length - 1; i += 1) {
156:     const a = world.route[i];
157:     const b = world.route[i + 1];
158:     const dx = b.x - a.x;
159:     const dy = b.y - a.y;
160:     const t = clamp(((x - a.x) * dx + (y - a.y) * dy) / (dx * dx + dy * dy || 1), 0, 1);
161:     const px = a.x + dx * t;
162:     const py = a.y + dy * t;
163:     const dist = Math.hypot(x - px, y - py);
164:     if (dist < best) best = dist;
165:   }
166:   return best;
167: }
