169: function getRiverDistance(x, y) {
170:   let best = Infinity;
171:   for (let i = 0; i < world.river.length - 1; i += 1) {
172:     const a = world.river[i];
173:     const b = world.river[i + 1];
174:     const dx = b.x - a.x;
175:     const dy = b.y - a.y;
176:     const t = clamp(((x - a.x) * dx + (y - a.y) * dy) / (dx * dx + dy * dy || 1), 0, 1);
177:     const px = a.x + dx * t;
178:     const py = a.y + dy * t;
179:     const dist = Math.hypot(x - px, y - py);
180:     if (dist < best) best = dist;
181:   }
182:   return best;
183: }
