185: function findNearestRoadPoint(x, y) {
186:   let nearest = null;
187:   let bestDistance = Infinity;
188:   for (let i = 0; i < world.route.length - 1; i += 1) {
189:     const a = world.route[i];
190:     const b = world.route[i + 1];
191:     const dx = b.x - a.x;
192:     const dy = b.y - a.y;
193:     const t = clamp(((x - a.x) * dx + (y - a.y) * dy) / (dx * dx + dy * dy || 1), 0, 1);
194:     const point = { x: a.x + dx * t, y: a.y + dy * t };
195:     const distance = distanceToPoint({ x, y }, point);
196:     if (distance < bestDistance) {
197:       bestDistance = distance;
198:       nearest = point;
199:     }
200:   }
201:   return { point: nearest, distance: bestDistance };
202: }
