266: function drawTopoMap() {
267:   const map = document.getElementById('topoMap');
268:   if (!map || document.getElementById('mapOverlay').hidden) return;
269: 
270:   const rect = map.getBoundingClientRect();
271:   if (!rect.width || !rect.height) return;
272:   const ratio = window.devicePixelRatio || 1;
273:   const pixelWidth = Math.round(rect.width * ratio);
274:   const pixelHeight = Math.round(rect.height * ratio);
275:   if (map.width !== pixelWidth || map.height !== pixelHeight) {
276:     map.width = pixelWidth;
277:     map.height = pixelHeight;
278:   }
279:   const mapCtx = map.getContext('2d');
280:   mapCtx.setTransform(ratio, 0, 0, ratio, 0, 0);
281:   mapCtx.clearRect(0, 0, rect.width, rect.height);
282:   mapCtx.fillStyle = '#28382d';
283:   mapCtx.fillRect(0, 0, rect.width, rect.height);
284: 
285:   const padding = 28;
286:   const scale = Math.min((rect.width - padding * 2) / world.width, (rect.height - padding * 2) / world.height);
287:   const offsetX = (rect.width - world.width * scale) / 2;
288:   const offsetY = (rect.height - world.height * scale) / 2;
289:   mapCtx.save();
290:   mapCtx.translate(offsetX, offsetY);
291:   mapCtx.scale(scale, scale);
