310:   mapCtx.stroke();
311:   mapCtx.setLineDash([12, 12]);
312:   mapCtx.strokeStyle = 'rgba(190, 229, 232, .8)';
313:   mapCtx.lineWidth = 2;
314:   mapCtx.stroke();
