320:   world.route.forEach((point, index) => index ? mapCtx.lineTo(point.x, point.y) : mapCtx.moveTo(point.x, point.y));
321:   mapCtx.stroke();
322:   mapCtx.strokeStyle = '#d7d4be';
323:   mapCtx.lineWidth = 18;
324:   mapCtx.stroke();
325:   mapCtx.setLineDash([18, 12]);
326:   mapCtx.strokeStyle = '#8f9a77';
327:   mapCtx.lineWidth = 2;
328:   mapCtx.stroke();
329:   mapCtx.setLineDash([]);
