333:     mapCtx.fillStyle = state.objectiveCompleted[index] ? '#899582' : index === state.missionIndex ? '#d6e35a' : '#d7d4be';
334:     mapCtx.arc(stop.x, stop.y, index === state.missionIndex && !state.objectiveCompleted[index] ? 15 : 10, 0, Math.PI * 2);
