474: function drawWorld() {
475:   const viewX = player.x - canvas.clientWidth / 2;
476:   const viewY = player.y - canvas.clientHeight / 2;
477:   const visibleW = canvas.clientWidth;
478:   const visibleH = canvas.clientHeight;
479: 
480:   ctx.clearRect(0, 0, visibleW, visibleH);
481:   ctx.fillStyle = '#1c2a23';
482:   ctx.fillRect(0, 0, visibleW, visibleH);
483: 
484:   const startX = Math.floor((viewX - 40) / world.tile) * world.tile;
485:   const startY = Math.floor((viewY - 40) / world.tile) * world.tile;
486:   const endX = Math.ceil((viewX + visibleW + 40) / world.tile) * world.tile;
487:   const endY = Math.ceil((viewY + visibleH + 40) / world.tile) * world.tile;
488: 
489:   for (let y = startY; y < endY; y += world.tile) {
490:     for (let x = startX; x < endX; x += world.tile) {
491:       const terrain = sampleTerrain(x + world.tile * 0.5, y + world.tile * 0.5);
492:       const px = x - viewX;
493:       const py = y - viewY;
494:       ctx.fillStyle = terrain.color;
495:       ctx.fillRect(px, py, world.tile + 1, world.tile + 1);
496:     }
497:   }
498: 
499:   ctx.lineCap = 'round';
500:   ctx.lineJoin = 'round';
501:   ctx.strokeStyle = '#7f8d66';
502:   ctx.lineWidth = 22;
503:   ctx.beginPath();
504:   world.route.forEach((point, idx) => {
505:     const px = point.x - viewX;
506:     const py = point.y - viewY;
