673: function updateState(dt) {
674:   const stats = getVehicleStats();
675:   let terrain = sampleTerrain(player.x, player.y);
676:   const maxSpeed = stats.maxSpeed;
677:   const angularForce = state.lowRange ? 1.1 : 0.9;
678:   const softGround = terrain.type === 'mud' || terrain.type === 'peat' || terrain.type === 'snow';
679:   const pressureBonus = softGround && state.tirePressure <= 18 ? 0.12 + (state.build.beadlocks ? 0.08 : 0) : 0;
680:   const terrainUpgradeBonus = (state.build.boggers && (terrain.type === 'mud' || terrain.type === 'peat') ? 0.18 : 0)
681:     + (state.build.chains && terrain.type === 'snow' ? 0.15 : 0);
682:   const effectiveTraction = clamp(terrain.traction * stats.traction * stats.diffMul * (state.awd ? 1 : 0.72) * (1 + pressureBonus + terrainUpgradeBonus), 0.12, 1.4);
683: 
684:   if (keyState.KeyW) {
685:     player.speed += stats.acceleration * dt * effectiveTraction;
686:   }
687:   if (keyState.KeyS) {
688:     player.speed -= stats.braking * dt * 0.78;
689:   }
690:   if (!keyState.KeyW && !keyState.KeyS) {
691:     player.speed *= 0.98 * terrain.drag;
692:   }
693: 
694:   if (keyState.KeyA) {
695:     player.dir -= dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
696:   }
697:   if (keyState.KeyD) {
698:     player.dir += dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
699:   }
700: 
701:   player.speed = clamp(player.speed, -16, maxSpeed);
702: 
703:   const turnSlip = Math.abs((keyState.KeyA || keyState.KeyD) ? player.speed * 0.12 : 0);
704:   const surfaceBreak = terrain.surface * (state.build.boggers ? 0.85 : 1);
705:   player.slip = clamp((Math.abs(player.speed) / (stats.maxSpeed + 1)) * 100 * (1 / effectiveTraction) * surfaceBreak + turnSlip, 0, 100);
706: 
707:   if (Math.abs(player.speed) < 4 && (keyState.KeyA || keyState.KeyD)) {
708:     player.slip *= 0.7;
709:   }
710: 
711:   const sideways = Math.sin(player.dir) * player.speed;
712:   const forward = Math.cos(player.dir) * player.speed;
713:   player.x += forward * dt * 16;
714:   player.y += sideways * dt * 16;
715: 
716:   player.x = clamp(player.x, 30, world.width - 30);
717:   player.y = clamp(player.y, 30, world.height - 30);
718:   terrain = sampleTerrain(player.x, player.y);
719: 
720:   if (terrain.type === 'water') {
721:     const riverPush = 0.15 + (player.speed * 0.02);
722:     player.x += Math.cos(Math.PI * 0.5) * riverPush * dt * 80;
723:     player.y += Math.sin(Math.PI * 0.75) * riverPush * dt * 48;
724:     player.waterDepth = clamp(1.05 * (1 - getRiverDistance(player.x, player.y) / 50), 0.05, 1.05);
725:   } else {
726:     player.waterDepth = 0;
727:   }
728: 
729:   if (terrain.type === 'peat') {
730:     player.speed *= 0.994;
731:     if (Math.abs(player.speed) < 3) player.speed *= 0.98;
732:   }
733: 
734:   if (terrain.type === 'mud') {
735:     player.speed *= 0.996;
736:   }
737: 
738:   if (terrain.type === 'snow') {
739:     player.speed *= 0.999;
740:   }
741: 
742:   if (terrain.type === 'rock') {
743:     player.speed *= 0.999;
744:     player.chassis = clamp(player.chassis - 0.01 * (1 - stats.shockProtection), 0, 100);
745:   }
746: 
747:   if (terrain.type === 'water') {
748:     const waterSpeed = Math.abs(player.speed);
749:     const overFordLimit = player.waterDepth > stats.fordDepth;
750:     const fastUnsnorkelledCrossing = waterSpeed > 12 && !state.build.snorkel;
751:     const crossingDamage = overFordLimit
752:       ? (state.build.sealedIgnition ? 0.025 : 0.065) * (fastUnsnorkelledCrossing ? 1.35 : 1)
753:       : 0.008;
754:     player.engine = clamp(player.engine - crossingDamage * (state.build.radiatorRelocation ? 0.88 : 1) * dt * 60, 0, 100);
755:     if (player.waterDepth > stats.fordDepth + 0.15) {
756:       player.chassis = clamp(player.chassis - 0.012 * dt * 60, 0, 100);
757:     }
758:   }
759: 
760:   if (state.winchActive && state.winchAnchor) {
761:     const hook = getWinchHookPosition();
762:     const dx = state.winchAnchor.x - hook.x;
763:     const dy = state.winchAnchor.y - hook.y;
764:     const distance = Math.hypot(dx, dy);
765:     if (distance > 12) {
766:       const pull = Math.min(distance - 12, stats.recoveryPower * 9 * dt);
767:       player.x += (dx / distance) * pull;
768:       player.y += (dy / distance) * pull;
769:       player.speed *= 0.92;
770:     } else {
771:       state.winchActive = false;
772:       state.winchAnchor = null;
773:       showToast('WINCH ANCHOR REACHED');
774:     }
775:   }
776: 
777:   if (player.speed < 0) {
778:     player.selectedGear = 'R';
779:     player.gearMode = 'LOW';
780:   } else if (Math.abs(player.speed) > 0.5) {
781:     player.selectedGear = state.lowRange ? '2' : '4';
782:     player.gearMode = state.lowRange ? 'LOW' : 'HIGH';
783:   } else {
784:     player.selectedGear = 'N';
785:     player.gearMode = state.lowRange ? 'LOW' : 'HIGH';
786:   }
787: 
788:   player.rpm = 830 + Math.abs(player.speed) * 28 + (state.lowRange ? 150 : 0);
789:   player.fuel = clamp(player.fuel - Math.abs(player.speed) * 0.004 * dt * 60, 0, 100);
790:   player.tyres = clamp(player.tyres - (player.slip / 220) * stats.tireWearMultiplier * dt * 60, 0, 100);
791:   player.engine = clamp(player.engine - (player.slip / 210) * (state.build.radiatorRelocation ? 0.88 : 1) * dt * 60, 0, 100);
792:   player.chassis = clamp(player.chassis - (player.slip > 65 ? 0.015 : 0) * (1 - stats.shockProtection) * dt * 48, 0, 100);
793: 
794:   if (player.engine <= 10 || player.fuel <= 0) {
795:     player.speed *= 0.91;
796:   }
797: 
798:   const towFactor = state.build.winch ? 1.1 : 1;
799:   player.speed *= 0.999 + (0.001 * towFactor);
800: 
801:   const truckBias = state.build.portalAxles ? 0.12 : 0;
802:   if (terrain.type === 'road' && Math.abs(player.speed) < 10) {
803:     player.slip = clamp(player.slip * 0.97 - truckBias, 0, 100);
804:   }
805: 
806:   player.x = clamp(player.x, 30, world.width - 30);
807:   player.y = clamp(player.y, 30, world.height - 30);
808:   checkMission();
809:   updateVehicleUI();
810: }
